import numbers

def process_orders(orders):
    total = 0
    failed = []
    for x in orders:
        if isinstance(x, dict) and 'id' in x:
            q = x.get('quantity')
            a = x.get('amount')
            if isinstance(q, int) and isinstance(a, numbers.Number):
                total += a * q
            else:
                failed.append(x['id'])
    return {'revenue': total, 'failed_orders': failed}
